'use strict';

var log = require( './../custom_log.js' );

// MAIN //

/**
* Handles message of type `kernel_info_request`.
*
* @private
* @param {Message} request - `kernel_info_request`
* @returns {Message} `kernel_info_reply`
*/
function handleKernelInfoRequest( request ) {

	// log( 'Inside kernel info request' );
	// TODO: Change method names.
	// FIXME: Things are hardcoded as of now
	return request.createReply( 'kernel_info_reply', {
		'status': 'ok',
		'protocol_version': '5.2',
		'implementation': 'stdlib',
		'implementation_version': '1.0.0',
		'language_info': {
			'name': 'javascript',
			'version': '0.0.0',
			'mimetype': 'application/javascript',
			'file_extension': '.js',
			'pygments_lexer': 'javascript',
			'codemirror_mode': 'JavaScript',
			'nbconvert_exporter': 'script'
		},
		'banner': 'This is stdlib!!'
		// 'debugger': 'false,
		// help links
	});
}


// EXPORTS //

module.exports = handleKernelInfoRequest;
